string encode(vector<string>& strs) {
    string out;
    for (auto& w : strs)
      for (char ch : w) {
        if (ch == '/') out += "//";
        else if (ch == '#') out += "/#";
        else out += ch;
      }
      out += '#';
    return out;
}

